export function seedCollocations(db: Database.Database) {
  const count = db.prepare('SELECT COUNT(*) as count FROM collocations').get() as any;

  // Only seed on first run; re-seeding every boot would wipe user-added words
  // (source = 'custom') and all mastery/review progress.
  if (count.count > 0) {
    console.log(`Collocations table already has ${count.count} entries, skipping seed`);
    // Always ensure reading vocabulary exists even if main seed was already done
    addReadingVocab(db);
    return;
  }

  const insert = db.prepare(
    `INSERT INTO collocations (id, phrase, definition, writing_task1_example, writing_task2_example, speaking_example, context, date_added, mastered, topics, level, last_reviewed, next_review, review_count)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  );

  const now = new Date().toISOString();

  const insertMany = db.transaction((items: CollocationSeed[]) => {
    for (const item of items) {
      insert.run(
        crypto.randomUUID(),
        item.phrase,
        item.definition,
        item.writingTask1Example,
        item.writingTask2Example,
        item.speakingExample,
        'both',
        now,
        0,
        JSON.stringify([item.topic]),
        0,
        '',
        '',
        0
      );
    }
  });

  insertMany(collocations);
  console.log(`Seeded ${collocations.length} collocations across 42 topics`);
}

interface ReadingVocabSeed {
  phrase: string;
  definition: string;
  synonyms: string[];
  topic: string;
}

function addReadingVocab(db: Database.Database) {
  const readingVocab: ReadingVocabSeed[] = [
    { phrase: 'global variation', definition: 'Differences across the world; variety of forms in different parts of the world.', synonyms: ['variety of forms', 'different parts of the world'], topic: 'science, research & space' },
    { phrase: 'cautionary', definition: 'Giving warnings about possible dangers or problems.', synonyms: ['warning', 'advisory'], topic: 'psychology & human behavior' },
    { phrase: 'survival-relevant', definition: 'Important for staying alive; related to survival.', synonyms: ['important for staying alive'], topic: 'wildlife, nature & animals' },
    { phrase: 'phylogenetic', definition: 'Relating to the evolutionary relationships between species.', synonyms: ['evolutionary', 'relating to species development'], topic: 'science, research & space' },
    { phrase: 'evolutionary', definition: 'Relating to how things develop and change over time.', synonyms: ['relating to how things develop over time'], topic: 'science, research & space' },
    { phrase: 'conserved', definition: 'Kept or preserved unchanged; maintained in its original form.', synonyms: ['preserved', 'kept unchanged'], topic: 'science, research & space' },
    { phrase: 'trivial', definition: 'Unimportant; of little value or significance.', synonyms: ['unimportant', 'minor', 'negligible'], topic: 'psychology & human behavior' },
    { phrase: 'gruesome', definition: 'Very unpleasant; causing horror or disgust.', synonyms: ['macabre', 'horrifying', 'grisly'], topic: 'psychology & human behavior' },
    { phrase: 'gripping', definition: 'Very exciting; holding one\'s attention completely.', synonyms: ['compelling', 'riveting', 'engrossing'], topic: 'the arts, literature & creativity' },
    { phrase: 'devising', definition: 'Creating or inventing a plan, method, or system.', synonyms: ['creating', 'formulating', 'inventing'], topic: 'science, research & space' },
    { phrase: 'anthropologist', definition: 'Someone who studies human societies, cultures, and their development.', synonyms: ['someone who studies human cultures'], topic: 'history, archeology & the past' },
    { phrase: 'folklorist', definition: 'Someone who studies traditional stories, beliefs, and customs.', synonyms: ['someone who studies traditional stories'], topic: 'history, archeology & the past' },
    { phrase: 'attributed to', definition: 'Believed to be caused by or originating from.', synonyms: ['ascribed to', 'put down to'], topic: 'psychology & human behavior' },
    { phrase: 'insights', definition: 'A deep understanding or perception of something.', synonyms: ['understanding', 'awareness', 'perception'], topic: 'psychology & human behavior' },
  ];

  const existing = db.prepare('SELECT phrase FROM collocations').all() as { phrase: string }[];
  const existingPhrases = new Set(existing.map((e) => e.phrase.toLowerCase()));

  const now = new Date().toISOString();
  const insert = db.prepare(
    `INSERT INTO collocations (id, phrase, definition, writing_task1_example, writing_task2_example, speaking_example, context, date_added, mastered, topics, level, last_reviewed, next_review, review_count, note, source, synonyms)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  );

  let added = 0;
  for (const item of readingVocab) {
    if (!existingPhrases.has(item.phrase.toLowerCase())) {
      insert.run(
        crypto.randomUUID(),
        item.phrase,
        item.definition,
        '',
        '',
        '',
        'both',
        now,
        0,
        JSON.stringify([item.topic]),
        0,
        '',
        '',
        0,
        'Cambridge 15 Test 3 - Reading',
        'custom',
        JSON.stringify(item.synonyms)
      );
      added++;
    }
  }
  if (added > 0) {
    console.log(`Added ${added} reading vocabulary entries`);
  }
}
